                3'd2: Y2 = 1'b1;
                3'd3: Y3 = 1'b1;
                3'd4: Y4 = 1'b1;
                3'd5: Y5 = 1'b1;
                3'd6: Y6 = 1'b1;
                3'd7: Y7 = 1'b1;
            endcase
        end
    end
