import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();

// Block the actual network call so this test never spends a real Devin
// session even if the confirm-skip logic lets it through.
let runsRequested = 0;
await page.route("**/api/runs", (route) => {
  runsRequested++;
  route.fulfill({ status: 200, body: JSON.stringify({ run_id: "test", pid: 0 }) });
});

let dialogShown = false;
page.on("dialog", async (dialog) => {
  dialogShown = true;
  await dialog.dismiss();
});

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");

// Test 1: attempts=1 (default) -- should launch with NO dialog
await page.click("button:has-text('Launch Attempt')");
await page.waitForTimeout(500);
console.log("attempts=1 -> dialog shown:", dialogShown, "| request sent:", runsRequested === 1);

// Test 2: bump to attempts=4 -- SHOULD show a dialog, and dismissing blocks the request
dialogShown = false;
await page.fill("input[type=number]", "4");
await page.click("button:has-text('Launch Attempt')");
await page.waitForTimeout(500);
console.log("attempts=4 -> dialog shown:", dialogShown, "| request count still 1 (blocked):", runsRequested === 1);

