import { useEffect, useRef } from "react";

const MAX_LINES = 150;

// Chronological transcript of every 'running' event -- includes our own
// "creating session" / "polling" lines plus Devin's own narrated progress
// messages, surfaced purely for visibility. This is never how pass/fail is
// decided (that stays the harness's job); it's just watching it happen.
export default function ActivityFeed({ events }) {
  const bottomRef = useRef(null);
  const lines = events.filter((e) => e.status === "running").slice(-MAX_LINES);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: "end" });
  }, [lines.length]);

  return (
    <div className="activity-feed">
      <h3>Live Activity</h3>
      <div className="activity-feed-scroll">
        {lines.length === 0 && <div className="agent-status-empty">No activity yet</div>}
        {lines.map((e, i) => (
          <div className="activity-line" key={i}>
            <span className="activity-time">{formatTime(e.ts)}</span>
            <span className="activity-agent">{e.agent}</span>
            <span className="activity-text">{e.detail}</span>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
}

function formatTime(ts) {
  if (!ts) return "";
  const d = new Date(ts);
  return d.toLocaleTimeString([], { hour12: false });
}

const KEYWORDS = new Set([
  "module", "endmodule", "input", "output", "inout", "wire", "reg", "always",
  "assign", "begin", "end", "if", "else", "case", "endcase", "default",
  "posedge", "negedge", "parameter", "localparam", "function", "endfunction",
  "integer", "genvar", "generate", "endgenerate", "for", "while",
]);

// Tokenizes one line into { text, kind } pieces for syntax-colored spans.
// Returns React-safe data (no HTML strings) -- the caller renders each piece
// as its own <span>, so nothing here can inject markup even if the RTL text
// itself contains something that looks like HTML.
export function tokenizeLine(line) {
  const tokens = [];
  const commentIdx = line.indexOf("//");
  const code = commentIdx >= 0 ? line.slice(0, commentIdx) : line;
  const comment = commentIdx >= 0 ? line.slice(commentIdx) : "";

  const re = /(\d+'[bdhBDH][0-9a-fA-Fxz_]+|\b\d+\b|\b[a-zA-Z_]\w*\b|[^\sa-zA-Z_0-9]+|\s+)/g;
  let match;
  while ((match = re.exec(code)) !== null) {
    const word = match[0];
    let kind = "plain";
    if (/^\d+'[bdhBDH]/.test(word) || /^\d+$/.test(word)) kind = "number";
    else if (KEYWORDS.has(word)) kind = "keyword";
    tokens.push({ text: word, kind });
  }
  if (comment) tokens.push({ text: comment, kind: "comment" });
  return tokens;
}

import { useEffect, useState } from "react";
import { fetchBranchFile } from "../lib/api";
import { tokenizeLine } from "../lib/verilogHighlight";

const AGENT_PATH = {
  coder: (chip) => `rtl/${chip}.v`,
  style: (chip) => `rtl/${chip}.v`,
  testbencher: (chip) => `rtl/${chip}_tb_extra.v`,
};
const CODE_STAGES = new Set(["generate", "coverage", "cleanup"]);

function lastCodeEvent(events) {
  for (let i = events.length - 1; i >= 0; i--) {
    const e = events[i];
    if (e.status === "pass" && CODE_STAGES.has(e.stage) && AGENT_PATH[e.agent]) return e;
  }
  return null;
}

// Shows the ACTUAL committed RTL, fetched straight from the git branch --
// updates live as each agent (coder -> testbencher -> style) pushes its
// commit, so you watch the real code land rather than a waveform of a
// binary counter sweep.
export default function CodePanel({ events }) {
  const latest = lastCodeEvent(events);
  const [code, setCode] = useState(null);
  const [error, setError] = useState(null);

  const path = latest ? AGENT_PATH[latest.agent](latest.chip) : null;

  useEffect(() => {
    if (!latest) return;
    setCode(null);
    setError(null);
    fetchBranchFile(latest.branch, path)
      .then(setCode)
      .catch((e) => setError(String(e)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [latest?.branch, latest?.agent, latest?.ts]);

  if (!latest) return <div className="proof-empty">No code pushed yet</div>;
  if (error) return <div className="proof-empty">Could not load {path} ({error})</div>;
  if (!code) return <div className="proof-empty">Loading {path}…</div>;

  return (
    <div className="code-panel">
      <div className="code-panel-header">
        <span className="code-panel-agent">{latest.agent}</span> just wrote{" "}
        <span className="code-panel-path">{path}</span>
      </div>
      <pre className="code-panel-body">
        {code.split("\n").map((line, i) => (
          <div className="code-line" key={i}>
            <span className="code-line-no">{i + 1}</span>
            <span className="code-line-text">
              {tokenizeLine(line).map((tok, j) => (
                <span key={j} className={`tok-${tok.kind}`}>
                  {tok.text}
                </span>
              ))}
            </span>
          </div>
        ))}
      </pre>
    </div>
  );
}

