import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");
await page.click("button:has-text('Launch Attempt')");
console.log("launched, waiting for activity...");

await page.waitForSelector(".activity-line", { timeout: 30000 });
await page.waitForTimeout(3000);
await page.screenshot({ path: "scratch_live_1.png", fullPage: true });
console.log("screenshot 1 (early activity) taken");

console.log("console errors so far:", JSON.stringify(errors));
await browser.close();

