import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();

// Mock the run POST to resolve fast but never actually emit any SSE event,
// simulating the real gap between "subprocess spawned" and "first event".
await page.route("**/api/runs", (route) => {
  route.fulfill({ status: 200, body: JSON.stringify({ run_id: "fake", pid: 0 }) });
});

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");

await page.click("button:has-text('Launch Attempt')");
await page.waitForTimeout(1500);

const btnText = await page.$eval("button:has-text('Launching')", (el) => el.textContent).catch(() => null);
console.log("button text 1.5s after click:", btnText);

const coderStatus = await page.$eval(".pipeline-node .pipeline-node-status", (el) => el.textContent);
console.log("Coder node status 1.5s after click:", coderStatus);

await page.screenshot({ path: "scratch_loading.png", fullPage: true });
await browser.close();

